"""
Coinbase Financial Markets client.

Trades CFTC-regulated perpetual-style futures (the "nano PERP" contracts
that actually expire Dec 2030 but behave as perps). Uses the official
`coinbase-advanced-py` SDK with JWT ES256 auth.

Product IDs (discovered 2026-04-11):
    BTC -> BIP-20DEC30-CDE  (contract size 0.01 BTC)
    ETH -> ETP-20DEC30-CDE  (contract size 0.1 ETH)
    SOL -> SLP-20DEC30-CDE  (contract size 5 SOL)

Key quirks handled here:
  * Coinbase returns numeric fields as strings - we cast consistently
  * Contract margin rate != notional value; UI shows margin, we track notional
  * Hourly funding (vs 8h on Hyperliquid) - funding_time exposed per product
  * Positions for futures come from a different endpoint than spot balances
"""
from __future__ import annotations

import json
import logging
import math
from dataclasses import asdict
from pathlib import Path
from typing import Optional

import pandas as pd

from .base import ContractSpec, ExchangeClient, OrderResult, Position

logger = logging.getLogger(__name__)


# ---------------------------------------------------------------------------
# Hardcoded product specs for the 3 coins we trade
# ---------------------------------------------------------------------------
# Discovered from scripts/find_us_perps.py against the live API.
# If Coinbase ever adds new perp contracts, expand this table.

_PRODUCT_SPECS: dict[str, ContractSpec] = {
    "BTC": ContractSpec(
        symbol="BTC",
        product_id="BIP-20DEC30-CDE",
        contract_size=0.01,
        price_increment=1.0,
        min_notional_usd=10.0,
        overnight_margin_rate=0.2456,
        intraday_margin_rate=0.10,
    ),
    "ETH": ContractSpec(
        symbol="ETH",
        product_id="ETP-20DEC30-CDE",
        contract_size=0.1,
        price_increment=0.01,
        min_notional_usd=10.0,
        overnight_margin_rate=0.2466,
        intraday_margin_rate=0.10,
    ),
    "SOL": ContractSpec(
        symbol="SOL",
        product_id="SLP-20DEC30-CDE",
        contract_size=5.0,
        price_increment=0.001,
        min_notional_usd=10.0,
        overnight_margin_rate=0.25,  # placeholder, refreshed from API on init
        intraday_margin_rate=0.10,
    ),
}

# Granularity mapping for candle intervals.
# Coinbase Advanced Trade API uses string enums like ONE_MINUTE / FIFTEEN_MINUTE.
_GRANULARITY_MAP = {
    "1m": "ONE_MINUTE",
    "5m": "FIVE_MINUTE",
    "15m": "FIFTEEN_MINUTE",
    "30m": "THIRTY_MINUTE",
    "1h": "ONE_HOUR",
    "2h": "TWO_HOUR",
    "6h": "SIX_HOUR",
    "1d": "ONE_DAY",
}


def _to_float(value, default: float = 0.0) -> float:
    """Coinbase returns numerics as strings - cast defensively."""
    if value is None or value == "":
        return default
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def _to_dict(obj) -> dict:
    """Some SDK responses are dicts, others are objects with __dict__."""
    if isinstance(obj, dict):
        return obj
    return getattr(obj, "__dict__", {}) or {}


class CoinbaseClient(ExchangeClient):
    """Live Coinbase perpetual futures client."""

    def __init__(
        self,
        key_file: Optional[str] = None,
        dry_run_default: bool = True,
    ):
        """
        Args:
            key_file: Path to Coinbase API key JSON. Defaults to
                secrets/coinbase_api.json relative to repo root.
            dry_run_default: If True, place_market_order() defaults to dry_run.
                Flip this to False explicitly when ready for live execution.
        """
        from coinbase.rest import RESTClient  # local import; optional dep

        if key_file is None:
            repo_root = Path(__file__).resolve().parents[1]
            key_file = str(repo_root / "secrets" / "coinbase_api.json")

        with open(key_file) as f:
            key_data = json.load(f)

        self._client = RESTClient(
            api_key=key_data["name"],
            api_secret=key_data["privateKey"],
        )
        self._dry_run_default = dry_run_default
        self._product_specs = dict(_PRODUCT_SPECS)
        self._refresh_margin_rates()

    # ---------- identification ----------
    @property
    def name(self) -> str:
        return "coinbase"

    def contract_specs(self) -> dict[str, ContractSpec]:
        return dict(self._product_specs)

    def _product_id(self, symbol: str) -> str:
        return self._product_specs[symbol].product_id

    def _refresh_margin_rates(self) -> None:
        """Pull fresh margin rates from the API for SOL (which was a placeholder)."""
        try:
            for sym, spec in self._product_specs.items():
                try:
                    resp = self._client.get_product(product_id=spec.product_id)
                    pd_ = _to_dict(resp)
                    details = pd_.get("future_product_details") or {}
                    if isinstance(details, dict):
                        overnight = (details.get("overnight_margin_rate") or {})
                        intraday = (details.get("intraday_margin_rate") or {})
                        if isinstance(overnight, dict) and overnight.get("long_margin_rate"):
                            spec.overnight_margin_rate = _to_float(
                                overnight.get("long_margin_rate"), spec.overnight_margin_rate
                            )
                        if isinstance(intraday, dict) and intraday.get("long_margin_rate"):
                            spec.intraday_margin_rate = _to_float(
                                intraday.get("long_margin_rate"), spec.intraday_margin_rate
                            )
                except Exception as e:
                    logger.debug("Could not refresh margin for %s: %s", sym, e)
        except Exception as e:
            logger.debug("Margin refresh skipped: %s", e)

    # ---------- market data ----------
    def fetch_current_price(self, symbol: str) -> float:
        """Live mark price for a symbol."""
        pid = self._product_id(symbol)
        resp = self._client.get_product(product_id=pid)
        pd_ = _to_dict(resp)
        # Prefer index_price (fair value) over settlement_price (stale)
        details = pd_.get("future_product_details") or {}
        if isinstance(details, dict):
            idx = _to_float(details.get("index_price"))
            if idx > 0:
                return idx
        # Fallback: product-level price
        return _to_float(pd_.get("price"))

    def fetch_funding_rate(self, symbol: str) -> float:
        """Current funding rate per 8h (Coinbase settles hourly; we report 8h equivalent)."""
        pid = self._product_id(symbol)
        resp = self._client.get_product(product_id=pid)
        pd_ = _to_dict(resp)
        details = pd_.get("future_product_details") or {}
        if isinstance(details, dict):
            # Coinbase returns hourly funding rate; multiply by 8 for 8h equivalent
            hourly = _to_float(details.get("funding_rate"))
            return hourly * 8
        return 0.0

    def fetch_candles(
        self,
        symbol: str,
        interval: str,
        start_ms: int,
        end_ms: int,
    ) -> pd.DataFrame:
        """
        Fetch OHLCV candles. Coinbase caps at 350 candles per request,
        so we chunk if the range is larger.
        """
        granularity = _GRANULARITY_MAP.get(interval)
        if granularity is None:
            raise ValueError(f"Unsupported interval: {interval}")

        pid = self._product_id(symbol)
        interval_seconds = {
            "1m": 60, "5m": 300, "15m": 900, "30m": 1800,
            "1h": 3600, "2h": 7200, "6h": 21600, "1d": 86400,
        }[interval]

        start_sec = start_ms // 1000
        end_sec = end_ms // 1000
        chunk_seconds = 300 * interval_seconds  # stay under 350 limit

        frames = []
        cursor = start_sec
        while cursor < end_sec:
            chunk_end = min(cursor + chunk_seconds, end_sec)
            try:
                resp = self._client.get_public_candles(
                    product_id=pid,
                    start=str(cursor),
                    end=str(chunk_end),
                    granularity=granularity,
                )
                pd_ = _to_dict(resp)
                candles = pd_.get("candles", [])
                if candles is None:
                    candles = []
                for c in candles:
                    cd = _to_dict(c)
                    frames.append({
                        "timestamp": int(_to_float(cd.get("start"))) * 1000,
                        "open": _to_float(cd.get("open")),
                        "high": _to_float(cd.get("high")),
                        "low": _to_float(cd.get("low")),
                        "close": _to_float(cd.get("close")),
                        "volume": _to_float(cd.get("volume")),
                    })
            except Exception as e:
                logger.warning("Candle fetch failed for %s %s: %s", symbol, interval, e)
            cursor = chunk_end

        if not frames:
            return pd.DataFrame(columns=["timestamp", "open", "high", "low", "close", "volume"])
        df = pd.DataFrame(frames)
        df = df.drop_duplicates(subset="timestamp").sort_values("timestamp").reset_index(drop=True)
        return df

    # ---------- account ----------
    def _get_futures_balance_summary(self) -> dict:
        """Fetch CFM futures balance summary as a plain dict.

        This is the ONLY source of truth for futures-aware cash/equity,
        because the regular get_accounts() endpoint only sees the spot USD
        balance and misses funds sitting in the CFM sub-account or in
        pending transfers between spot and futures.

        Normalizes across three response shapes the SDK has returned:
          - dict (direct JSON)
          - string repr of a dict (older SDK versions)
          - typed object with __dict__ (newer SDK versions)
        """
        def deep_dictify(obj):
            """Recursively convert SDK response objects to plain dicts."""
            if isinstance(obj, dict):
                return {k: deep_dictify(v) for k, v in obj.items()}
            if isinstance(obj, list):
                return [deep_dictify(v) for v in obj]
            if hasattr(obj, "__dict__"):
                return deep_dictify(obj.__dict__)
            return obj

        try:
            resp = self._client.get_futures_balance_summary()
            rd = deep_dictify(resp)
            summary = rd.get("balance_summary", {}) if isinstance(rd, dict) else {}

            # Handle legacy string-repr case
            if isinstance(summary, str):
                import ast
                try:
                    summary = ast.literal_eval(summary)
                except Exception:
                    summary = {}

            return summary if isinstance(summary, dict) else {}
        except Exception as e:
            logger.error("get_futures_balance_summary failed: %s", e)
            return {}

    def _summary_value(self, summary: dict, key: str) -> float:
        """Extract a float from a {value, currency, cbrn} nested struct."""
        field = summary.get(key, {}) if isinstance(summary, dict) else {}
        if isinstance(field, dict):
            return _to_float(field.get("value"))
        return _to_float(field)

    def get_cash_balance_usd(self) -> float:
        """USD available for futures trading (futures-aware, not spot-only).

        Returns the CFM available_margin, which accounts for:
          - Spot USD balance (cbi_usd_balance)
          - Futures sub-account balance (cfm_usd_balance)
          - Margin locked by open positions
          - Realized/unrealized P&L
          - Pending transfers between spot and futures
        """
        summary = self._get_futures_balance_summary()
        if not summary:
            # Fallback: sum USD spot balances (less accurate but better than 0)
            try:
                resp = self._client.get_accounts()
                pd_ = _to_dict(resp)
                accts = pd_.get("accounts", []) or []
                total_usd = 0.0
                for a in accts:
                    ad = _to_dict(a)
                    if ad.get("currency") == "USD":
                        bal = ad.get("available_balance") or {}
                        if isinstance(bal, dict):
                            total_usd += _to_float(bal.get("value"))
                return total_usd
            except Exception as e:
                logger.error("get_cash_balance_usd fallback failed: %s", e)
                return 0.0
        return self._summary_value(summary, "available_margin")

    def get_positions(self) -> dict[str, Position]:
        """
        Fetch open futures positions.

        Uses the CFM positions endpoint. Returns {symbol: Position} for any
        symbol we trade (BTC/ETH/SOL); symbols not in our universe are ignored.
        """
        positions: dict[str, Position] = {}
        try:
            # The SDK method for futures positions
            resp = self._client.list_futures_positions()
            pd_ = _to_dict(resp)
            pos_list = pd_.get("positions", [])
            if pos_list is None:
                pos_list = []
            product_to_symbol = {
                spec.product_id: sym
                for sym, spec in self._product_specs.items()
            }
            for p in pos_list:
                pd_p = _to_dict(p)
                pid = pd_p.get("product_id", "")
                if pid not in product_to_symbol:
                    continue
                symbol = product_to_symbol[pid]
                spec = self._product_specs[symbol]

                # Contracts: positive = long, negative = short
                # Coinbase may use "net_size", "number_of_contracts", or similar
                contracts = _to_float(
                    pd_p.get("number_of_contracts")
                    or pd_p.get("net_size")
                    or pd_p.get("contracts")
                )
                # Side flag may indicate short
                side = pd_p.get("side", "") or pd_p.get("position_side", "")
                if isinstance(side, str) and "SHORT" in side.upper() and contracts > 0:
                    contracts = -contracts

                entry_price = _to_float(pd_p.get("entry_vwap") or pd_p.get("avg_entry_price"))
                mark_price = _to_float(pd_p.get("current_price") or pd_p.get("mark_price"))
                if mark_price == 0:
                    mark_price = self.fetch_current_price(symbol)
                unrealized = _to_float(pd_p.get("unrealized_pnl"))

                notional = contracts * spec.contract_size * mark_price
                positions[symbol] = Position(
                    symbol=symbol,
                    contracts=contracts,
                    notional_usd=notional,
                    entry_price=entry_price,
                    mark_price=mark_price,
                    unrealized_pnl_usd=unrealized,
                )
        except Exception as e:
            # If the endpoint doesn't exist or fails, return empty - strategy
            # starts flat. Safer than crashing.
            logger.warning("get_positions failed (returning empty): %s", e)
        return positions

    def get_equity_usd(self) -> float:
        """Total equity in the trading account.

        Uses CFM `total_usd_balance` which is the full account value
        (spot + futures sub-account + margin + unrealized PnL).
        """
        summary = self._get_futures_balance_summary()
        if summary:
            total = self._summary_value(summary, "total_usd_balance")
            if total > 0:
                return total
        # Fallback
        cash = self.get_cash_balance_usd()
        pnl = sum(p.unrealized_pnl_usd for p in self.get_positions().values())
        return cash + pnl

    def get_futures_buying_power(self) -> float:
        """Futures-specific buying power (can be > cash if using leverage)."""
        summary = self._get_futures_balance_summary()
        return self._summary_value(summary, "futures_buying_power")

    def get_daily_realized_pnl(self) -> float:
        """Today's realized P&L from closed positions (price movement only, NOT including fees).

        WARNING: Coinbase's daily_realized_pnl field excludes fees. Use
        get_daily_total_pnl() for a complete picture.
        """
        summary = self._get_futures_balance_summary()
        return self._summary_value(summary, "daily_realized_pnl")

    def get_daily_total_fees(self) -> float:
        """
        Sum total fees from all filled orders for the current UTC calendar day.

        Queries the orders endpoint and filters to today's filled orders.
        Returns positive USD amount (fees are a cost, not signed).
        """
        from datetime import datetime, timezone
        today_str = datetime.now(timezone.utc).strftime("%Y-%m-%d")
        total_fees = 0.0
        try:
            for product_id in (spec.product_id for spec in self._product_specs.values()):
                try:
                    resp = self._client.list_orders(
                        product_id=product_id,
                        limit=100,
                        order_status=["FILLED"],
                    )
                    rd = _to_dict(resp)
                    orders = rd.get("orders", []) or []
                    for o in orders:
                        od = _to_dict(o)
                        created = str(od.get("created_time", ""))
                        if not created.startswith(today_str):
                            continue
                        fee = _to_float(od.get("total_fees"))
                        total_fees += fee
                except Exception as e:
                    logger.warning("Failed to list orders for %s: %s", product_id, e)
        except Exception as e:
            logger.error("get_daily_total_fees failed: %s", e)
        return total_fees

    def get_daily_total_pnl(self) -> float:
        """
        Complete daily P&L including fees: price P&L minus fees.

        Use this for risk monitoring where fees matter (e.g. daily loss cap).
        """
        return self.get_daily_realized_pnl() - self.get_daily_total_fees()

    def get_pending_transfers(self) -> float:
        """Amount currently in-flight between spot and futures sub-accounts."""
        summary = self._get_futures_balance_summary()
        return self._summary_value(summary, "total_pending_transfers_amount")

    def get_order_fill_details(self, order_id: str) -> tuple[float, float, float]:
        """
        Query a filled order to get the ACTUAL execution details from Coinbase.

        Returns (average_filled_price, total_fees, filled_contracts).
        These reflect what Coinbase actually settled, not the pre-order estimate.
        """
        try:
            resp = self._client.get_order(order_id)
            o = resp if isinstance(resp, dict) else (
                vars(resp) if hasattr(resp, "__dict__") else {}
            )
            order = o.get("order", o)
            if not isinstance(order, dict):
                order = vars(order) if hasattr(order, "__dict__") else {}

            avg_price = _to_float(order.get("average_filled_price"))
            total_fees = _to_float(order.get("total_fees"))
            filled = _to_float(order.get("filled_size"))
            return avg_price, total_fees, filled
        except Exception as e:
            logger.warning("get_order_fill_details(%s) failed: %s", order_id, e)
            return 0.0, 0.0, 0.0

    # ---------- order execution ----------
    def place_market_order(
        self,
        symbol: str,
        target_notional_usd: float,
        dry_run: Optional[bool] = None,
    ) -> OrderResult:
        """
        Move position to target_notional_usd (signed).

        Steps:
          1. Get current price for the symbol
          2. Get current position (if any)
          3. Convert current + target to contract counts
          4. Compute delta contracts to trade
          5. If abs(delta) < 1, skip (nothing to do)
          6. Place market order for delta contracts (or log if dry_run)
        """
        if dry_run is None:
            dry_run = self._dry_run_default

        spec = self._product_specs.get(symbol)
        if spec is None:
            return OrderResult(
                success=False,
                order_id=None,
                symbol=symbol,
                side="NONE",
                contracts=0,
                notional_usd=0,
                fill_price=None,
                error_message=f"Unknown symbol: {symbol}",
                dry_run=dry_run,
            )

        try:
            current_price = self.fetch_current_price(symbol)
        except Exception as e:
            return OrderResult(
                success=False,
                order_id=None,
                symbol=symbol,
                side="NONE",
                contracts=0,
                notional_usd=0,
                fill_price=None,
                error_message=f"Price fetch failed: {e}",
                dry_run=dry_run,
            )

        if current_price <= 0:
            return OrderResult(
                success=False,
                order_id=None,
                symbol=symbol,
                side="NONE",
                contracts=0,
                notional_usd=0,
                fill_price=None,
                error_message="Invalid price (<=0)",
                dry_run=dry_run,
            )

        # Current position (contracts)
        positions = self.get_positions()
        current_contracts = positions.get(symbol).contracts if symbol in positions else 0

        # Target contracts (rounded to nearest for best leverage match at small capital)
        target_contracts = self.notional_to_contracts(
            symbol, target_notional_usd, current_price, round_mode="nearest"
        )

        delta_contracts = int(target_contracts - current_contracts)
        if delta_contracts == 0:
            return OrderResult(
                success=True,
                order_id=None,
                symbol=symbol,
                side="SKIP",
                contracts=0,
                notional_usd=0,
                fill_price=current_price,
                dry_run=dry_run,
            )

        side = "BUY" if delta_contracts > 0 else "SELL"
        abs_contracts = abs(delta_contracts)
        notional = abs_contracts * spec.contract_size * current_price

        # Minimum notional check
        if notional < spec.min_notional_usd:
            return OrderResult(
                success=False,
                order_id=None,
                symbol=symbol,
                side=side,
                contracts=delta_contracts,
                notional_usd=notional * (1 if delta_contracts > 0 else -1),
                fill_price=current_price,
                error_message=f"Below min notional ${spec.min_notional_usd}",
                dry_run=dry_run,
            )

        if dry_run:
            logger.info(
                "[DRY RUN] %s %s %d contracts ($%.2f notional) @ $%.2f",
                side, symbol, abs_contracts, notional, current_price,
            )
            return OrderResult(
                success=True,
                order_id="DRY_RUN",
                symbol=symbol,
                side=side,
                contracts=delta_contracts,
                notional_usd=notional * (1 if delta_contracts > 0 else -1),
                fill_price=current_price,
                dry_run=True,
            )

        # LIVE order
        try:
            import uuid
            client_order_id = str(uuid.uuid4())
            if side == "BUY":
                resp = self._client.market_order_buy(
                    client_order_id=client_order_id,
                    product_id=spec.product_id,
                    base_size=str(abs_contracts),
                )
            else:
                resp = self._client.market_order_sell(
                    client_order_id=client_order_id,
                    product_id=spec.product_id,
                    base_size=str(abs_contracts),
                )
            pd_ = _to_dict(resp)
            success_response = pd_.get("success_response") or {}
            order_id = success_response.get("order_id") if isinstance(success_response, dict) else None
            return OrderResult(
                success=pd_.get("success", False),
                order_id=order_id,
                symbol=symbol,
                side=side,
                contracts=delta_contracts,
                notional_usd=notional * (1 if delta_contracts > 0 else -1),
                fill_price=current_price,
                dry_run=False,
                raw_response=pd_,
            )
        except Exception as e:
            logger.error("Order placement failed: %s", e)
            return OrderResult(
                success=False,
                order_id=None,
                symbol=symbol,
                side=side,
                contracts=delta_contracts,
                notional_usd=notional * (1 if delta_contracts > 0 else -1),
                fill_price=current_price,
                error_message=str(e),
                dry_run=False,
            )

def _download_hl_candles(symbol: str, interval: str, start_ms: int, end_ms: int) -> pd.DataFrame:
    """Download OHLCV candles from Hyperliquid."""
    interval_ms = INTERVAL_CONFIG[interval]["minutes"] * 60 * 1000
    all_rows = []
    current = start_ms
    chunk_ms = 30 * 24 * 3600 * 1000
    while current < end_ms:
        body = {
            "type": "candleSnapshot",
            "req": {
                "coin": symbol,
                "interval": interval,
                "startTime": current,
                "endTime": min(current + chunk_ms, end_ms),
            }
        }
        try:
            resp = _http_session.post(HL_INFO_URL, json=body, timeout=30)
            resp.raise_for_status()
            data = resp.json()
            if not isinstance(data, list) or not data:
                current += chunk_ms
                continue
            for row in data:
                all_rows.append({
                    "timestamp": int(row["t"]),
                    "open": float(row["o"]),
                    "high": float(row["h"]),
                    "low": float(row["l"]),
                    "close": float(row["c"]),
                    "volume": float(row["v"]),
                })
            current = int(data[-1]["t"]) + interval_ms
        except requests.exceptions.Timeout:
            logger.warning(f"Timeout downloading {symbol} candles at {current}")
            current += chunk_ms
        except requests.exceptions.HTTPError as e:
            if e.response is not None and e.response.status_code == 429:
                logger.warning(f"Rate limited on {symbol} candles, backing off 60s")
                time.sleep(60)
                continue
            logger.error(f"HTTP error downloading {symbol} candles: {e}")
            raise
        except (KeyError, TypeError, ValueError) as e:
            logger.error(f"Malformed candle data for {symbol}: {e}")
            current += chunk_ms
        time.sleep(0.2)
    return pd.DataFrame(all_rows)


def _validate_downloaded_data(df: pd.DataFrame, symbol: str) -> list[str]:
    """Validate downloaded data before caching. Returns list of errors."""
    errors = []

    required_cols = {"timestamp", "open", "high", "low", "close", "volume"}
    missing = required_cols - set(df.columns)
    if missing:
        errors.append(f"Missing columns: {missing}")
        return errors

    if len(df) < 100:
